<?php
require_once(__DIR__.'/../../includes/load.php');require_once(__DIR__.'/../../config/app.php');require_once(__DIR__.'/funciones_checklist.php');
ensure_mantenimiento_ti_schema();require_permiso('mantenimiento_ti','editar');csrf_require();mti_chk_require_schema();
$findingId=(int)($_POST['hallazgo_id']??0);$action=(string)($_POST['accion']??'');$user=current_user();$userId=(int)($user['id']??0);
$finding=$db->fetch_assoc($db->query("SELECT * FROM activos_mantenimiento_hallazgos WHERE id={$findingId} LIMIT 1"));if(!$finding){$session->msg('d','Hallazgo no encontrado.');redirect('hallazgos.php',false);}
if($action==='accion_estado'){$actionId=(int)($_POST['accion_id']??0);$state=(string)($_POST['estado']??'');$result=trim((string)($_POST['resultado']??''));if(!in_array($state,['PENDIENTE','EN_PROCESO','EJECUTADA','CANCELADA'],true)){$session->msg('d','Estado de accion no valido.');redirect('hallazgo.php?id='.$findingId,false);}if(in_array($state,['EJECUTADA','CANCELADA'],true)&&$result===''){$session->msg('d','Ejecutar o cancelar una accion requiere resultado o motivo.');redirect('hallazgo.php?id='.$findingId,false);}$row=$db->fetch_assoc($db->query("SELECT estado FROM activos_mantenimiento_hallazgo_acciones WHERE id={$actionId} AND hallazgo_id={$findingId} LIMIT 1"));if(!$row){$session->msg('d','Accion no valida.');redirect('hallazgo.php?id='.$findingId,false);}$date=$state==='EJECUTADA'?'NOW()':'NULL';$db->query("UPDATE activos_mantenimiento_hallazgo_acciones SET estado=".mti_chk_q($state).",resultado=".mti_chk_nullable($result).",fecha_inicio=IF(".mti_chk_q($state)."='EN_PROCESO',COALESCE(fecha_inicio,NOW()),fecha_inicio),fecha_ejecucion={$date} WHERE id={$actionId}");mti_chk_hallazgo_history($findingId,'ACCION_ESTADO',$row['estado'],$state,$result,$userId,$actionId);$session->msg('s','Estado de accion actualizado.');redirect('hallazgo.php?id='.$findingId,false);}
$newState=(string)($_POST['estado']??'');$comment=trim((string)($_POST['comentario']??''));$allowed=['ABIERTO'=>['EN_ATENCION','ANULADO'],'EN_ATENCION'=>['PENDIENTE_VERIFICACION','ANULADO'],'PENDIENTE_VERIFICACION'=>['EN_ATENCION','CERRADO','ANULADO'],'CERRADO'=>[],'ANULADO'=>[]];
if(!in_array($newState,$allowed[$finding['estado']]??[],true)){$session->msg('d','Transicion de estado no permitida.');redirect('hallazgo.php?id='.$findingId,false);}
$linkedCompleted=find_by_sql("SELECT a.id,a.estado,m.folio,m.trabajo_realizado FROM activos_mantenimiento_hallazgo_acciones a INNER JOIN activos_mantenimientos m ON m.id=a.mantenimiento_correctivo_id WHERE a.hallazgo_id={$findingId} AND a.estado IN ('PENDIENTE','EN_PROCESO') AND m.estado='COMPLETADO'");
foreach($linkedCompleted as $linkedAction){$actionId=(int)$linkedAction['id'];$result=trim((string)($linkedAction['trabajo_realizado']??''));if($result==='')$result='Accion ejecutada mediante la OT '.(string)$linkedAction['folio'];$db->query("UPDATE activos_mantenimiento_hallazgo_acciones SET estado='EJECUTADA',resultado=".mti_chk_q($result).",fecha_inicio=COALESCE(fecha_inicio,NOW()),fecha_ejecucion=NOW() WHERE id={$actionId} LIMIT 1");mti_chk_hallazgo_history($findingId,'ACCION_ESTADO',$linkedAction['estado'],'EJECUTADA','Sincronizada con OT completada '.(string)$linkedAction['folio'],$userId,$actionId);}
$pending=$db->fetch_assoc($db->query("SELECT COUNT(*) total FROM activos_mantenimiento_hallazgo_acciones WHERE hallazgo_id={$findingId} AND estado IN ('PENDIENTE','EN_PROCESO')"));
if(in_array($newState,['PENDIENTE_VERIFICACION','CERRADO'],true)&&(int)$pending['total']>0){$session->msg('d','No se puede avanzar mientras existan acciones pendientes.');redirect('hallazgo.php?id='.$findingId,false);}
if(in_array($newState,['PENDIENTE_VERIFICACION','CERRADO'],true)&&($finding['criticidad']==='CRITICA'||(int)$finding['requiere_parada']===1)){$totalActions=$db->fetch_assoc($db->query("SELECT COUNT(*) total FROM activos_mantenimiento_hallazgo_acciones WHERE hallazgo_id={$findingId}"));if((int)$totalActions['total']<1){$session->msg('d','Un hallazgo critico o con parada requiere al menos una accion.');redirect('hallazgo.php?id='.$findingId,false);}}
if($newState==='ANULADO'&&(!tiene_permiso('mantenimiento_ti','eliminar')||$comment==='')){$session->msg('d','Anular requiere permiso y motivo.');redirect('hallazgo.php?id='.$findingId,false);}
if($newState==='CERRADO'&&$comment===''){$session->msg('d','El cierre requiere resultado de verificacion.');redirect('hallazgo.php?id='.$findingId,false);}
if($newState==='CERRADO'){$verification=$db->fetch_assoc($db->query("SELECT COUNT(*) total FROM activos_mantenimiento_hallazgo_evidencias WHERE hallazgo_id={$findingId} AND etapa='VERIFICACION'"));if((int)$verification['total']<1){$session->msg('d','El cierre requiere al menos una evidencia de verificacion.');redirect('hallazgo.php?id='.$findingId,false);}}
$extra=$newState==='CERRADO'?",verificado_por={$userId},fecha_verificacion=NOW(),resultado_verificacion=".mti_chk_q($comment).",fecha_cierre=NOW()":($newState==='ANULADO'?',motivo_anulacion='.mti_chk_q($comment):'');
$db->query("UPDATE activos_mantenimiento_hallazgos SET estado=".mti_chk_q($newState).$extra." WHERE id={$findingId}");
mti_chk_hallazgo_history($findingId,'CAMBIO_ESTADO',$finding['estado'],$newState,$comment,$userId);$session->msg('s','Estado del hallazgo actualizado.');redirect('hallazgo.php?id='.$findingId,false);
